import React, { useState, useCallback, useEffect, Suspense } from 'react';
import { BrowserRouter, Route, Routes, useLocation } from 'react-router-dom';
import { useSpring, animated } from 'react-spring';
import { Particles } from "@tsparticles/react";
import { loadSlim } from "@tsparticles/slim";

import Navigation from './components/Navigation';
import LoadingScreen from './components/LoadingScreen';
import BackgroundCanvas from './components/BackgroundCanvas';

import './App.css';
import { GitHub, Linkedin, Mail } from 'react-feather';

// Lazy-load your main pages
const Home = React.lazy(() => import('./components/Home'));
const Skills = React.lazy(() => import('./components/Skills'));
const Experience = React.lazy(() => import('./components/Experience'));
const Projects = React.lazy(() => import('./components/Projects'));

function AppContent() {
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();

  useEffect(() => {
    // Simulate a loading screen
    const timer = setTimeout(() => setIsLoading(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  const particlesInit = useCallback(async (engine) => {
    await loadSlim(engine);
  }, []);

  const fadeIn = useSpring({
    opacity: isLoading ? 0 : 1,
    config: { duration: 1000 },
  });

  const sectionTransition = useSpring({
    opacity: 1,
    transform: 'translateY(0px)',
    from: { opacity: 0, transform: 'translateY(50px)' },
    reset: true,
    key: location.pathname,
  });

  const logoAnimation = useSpring({
    from: { opacity: 0, transform: 'scale(0.5)' },
    to: { opacity: 1, transform: 'scale(1)' },
    config: { tension: 300, friction: 10 },
  });

  // Pre-calculate social link animations
  const socialLinkAnimations = [
    useSpring({
      from: { opacity: 0, transform: 'translateY(20px)' },
      to: { opacity: 1, transform: 'translateY(0)' },
      delay: 200,
    }),
    useSpring({
      from: { opacity: 0, transform: 'translateY(20px)' },
      to: { opacity: 1, transform: 'translateY(0)' },
      delay: 400,
    }),
    useSpring({
      from: { opacity: 0, transform: 'translateY(20px)' },
      to: { opacity: 1, transform: 'translateY(0)' },
      delay: 600,
    }),
  ];

  if (isLoading) {
    return <LoadingScreen />;
  }

  return (
    <animated.div style={fadeIn} className="app">
      <BackgroundCanvas />

      <Particles
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 120,
          particles: {
            color: { value: '#ffffff' },
            links: {
              color: '#ffffff',
              distance: 150,
              enable: true,
              opacity: 0.5,
              width: 1,
            },
            move: { enable: true, speed: 0.5 },
            number: { value: 80 },
            opacity: { value: 0.5 },
            shape: { type: 'circle' },
            size: { value: { min: 1, max: 3 } },
          },
        }}
      />

      <header className="header">
        <animated.div className="logo" style={logoAnimation}>
          HP
        </animated.div>
        <div className="social-links">
          {[
            { icon: <GitHub size={20} />, url: 'https://github.com/het-patell', label: 'GitHub' },
            { icon: <Linkedin size={20} />, url: 'https://www.linkedin.com/in/het-patel-b35a8225b/', label: 'LinkedIn' },
            { icon: <Mail size={20} />, url: 'mailto:hetbhave@ualberta.ca', label: 'Email' },
          ].map(({ icon, url, label }, index) => (
            <animated.a
              key={url}
              href={url}
              target="_blank"
              rel="noopener noreferrer"
              className="social-link"
              aria-label={label}
              style={socialLinkAnimations[index]}
            >
              <span className="social-icon">{icon}</span>
            </animated.a>
          ))}
        </div>
      </header>

      <main className="main-content">
        <animated.div style={sectionTransition}>
          <Suspense fallback={<LoadingScreen />}>
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/skills" element={<Skills />} />
              <Route path="/experience" element={<Experience />} />
              <Route path="/projects" element={<Projects />} />
            </Routes>
          </Suspense>
        </animated.div>
      </main>

      <Navigation />
    </animated.div>
  );
}

function App() {
  return (
    <BrowserRouter basename="/my-portfolio">
      <AppContent />
    </BrowserRouter>
  );
}

export default App;

