import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Home, User, BarChart2, Briefcase } from 'lucide-react';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { id: 'home', icon: Home, path: '/', label: 'Home' },
    { id: 'skills', icon: BarChart2, path: '/skills', label: 'Skills' },
    { id: 'experience', icon: User, path: '/experience', label: 'Experience' },
    { id: 'projects', icon: Briefcase, path: '/projects', label: 'Projects' }
  ];

  return (
    <nav className="navigation">
      {navItems.map(({ id, icon: Icon, path, label }) => (
        <button
          key={id}
          className={`nav-item ${location.pathname === path ? 'active' : ''}`}
          onClick={() => navigate(path)}
          data-label={label} // For the tooltip
        >
          <Icon className="nav-icon" />
        </button>
      ))}
    </nav>
  );
};

export default Navigation;